#!/usr/bin/env python3
"""Build an academic DOCX directly from the generated analysis CSVs and PNGs."""
from __future__ import annotations
import csv, html, math, os, zipfile
from pathlib import Path

ROOT=Path(__file__).resolve().parents[3]
OUT=ROOT/"improvement"/"improvement_1"
DEST=Path(os.environ.get("POOLADAPT_REPORT_DEST", OUT/"PoolAdapt_CT1_Evaluation_Report.docx"))

def rows(path):
    with path.open(newline="",encoding="utf-8-sig") as f:return list(csv.DictReader(f))
def fnum(r,k):return float(r[k])
def esc(s):return html.escape(str(s),quote=False)

def p(text,style=None):
    sty=f'<w:pPr><w:pStyle w:val="{style}"/></w:pPr>' if style else ""
    return f'<w:p>{sty}<w:r><w:t xml:space="preserve">{esc(text)}</w:t></w:r></w:p>'

def table(headers,body,widths=None):
    cols=len(headers); widths=widths or [9000//cols]*cols
    border='<w:tblBorders><w:top w:val="single" w:sz="4" w:color="AAB4C3"/><w:left w:val="single" w:sz="4" w:color="AAB4C3"/><w:bottom w:val="single" w:sz="4" w:color="AAB4C3"/><w:right w:val="single" w:sz="4" w:color="AAB4C3"/><w:insideH w:val="single" w:sz="3" w:color="D4DAE3"/><w:insideV w:val="single" w:sz="3" w:color="D4DAE3"/></w:tblBorders>'
    def row(vals,head=False):
        cells=[]
        for i,v in enumerate(vals):
            shade='<w:shd w:fill="E8EEF7"/>' if head else ""
            cells.append(f'<w:tc><w:tcPr><w:tcW w:w="{widths[i]}" w:type="dxa"/>{shade}</w:tcPr><w:p><w:r><w:rPr>{"<w:b/>" if head else ""}<w:sz w:val="16"/></w:rPr><w:t xml:space="preserve">{esc(v)}</w:t></w:r></w:p></w:tc>')
        trpr='<w:trPr><w:tblHeader w:val="true"/><w:cantSplit/></w:trPr>' if head else '<w:trPr><w:cantSplit/></w:trPr>'
        return '<w:tr>'+trpr+''.join(cells)+'</w:tr>'
    return f'<w:tbl><w:tblPr><w:tblW w:w="0" w:type="auto"/><w:tblLayout w:type="fixed"/>{border}<w:tblCellMar><w:top w:w="70" w:type="dxa"/><w:bottom w:w="70" w:type="dxa"/><w:left w:w="70" w:type="dxa"/><w:right w:w="70" w:type="dxa"/></w:tblCellMar></w:tblPr>{row(headers,True)}{"".join(row(x) for x in body)}</w:tbl>'

def image_block(path:Path, rel_id:int, title:str, width_emu=6_100_000,height_emu=3_880_000):
    name=path.name
    drawing=f'''<w:p><w:pPr><w:jc w:val="center"/></w:pPr><w:r><w:drawing><wp:inline xmlns:wp="http://schemas.openxmlformats.org/drawingml/2006/wordprocessingDrawing" xmlns:a="http://schemas.openxmlformats.org/drawingml/2006/main" xmlns:pic="http://schemas.openxmlformats.org/drawingml/2006/picture" distT="0" distB="0" distL="0" distR="0"><wp:extent cx="{width_emu}" cy="{height_emu}"/><wp:docPr id="{rel_id}" name="{esc(name)}" descr="{esc(title)}"/><wp:cNvGraphicFramePr><a:graphicFrameLocks noChangeAspect="1"/></wp:cNvGraphicFramePr><a:graphic><a:graphicData uri="http://schemas.openxmlformats.org/drawingml/2006/picture"><pic:pic><pic:nvPicPr><pic:cNvPr id="{rel_id}" name="{esc(name)}"/><pic:cNvPicPr/></pic:nvPicPr><pic:blipFill><a:blip r:embed="rIdImg{rel_id}"/><a:stretch><a:fillRect/></a:stretch></pic:blipFill><pic:spPr><a:xfrm><a:off x="0" y="0"/><a:ext cx="{width_emu}" cy="{height_emu}"/></a:xfrm><a:prstGeom prst="rect"><a:avLst/></a:prstGeom></pic:spPr></pic:pic></a:graphicData></a:graphic></wp:inline></w:drawing></w:r></w:p>'''
    return drawing+p(title,"Caption")

def build():
    match=rows(OUT/"tables/matched_budget_summary.csv")
    stats=rows(OUT/"statistics/paired_statistical_analysis.csv")
    random_seeds=rows(OUT/"statistics/random_seed_sensitivity.csv")
    latency_sensitivity=rows(OUT/"latency_cost/random_latency_percentile_sensitivity.csv")
    allres=rows(OUT/"tables/main_results_summary.csv")
    lat=rows(OUT/"latency_cost/latency_cost_summary.csv")
    pareto=rows(OUT/"pareto/pareto_analysis.csv")
    cases=rows(OUT/"failure_analysis/failure_case_analysis.csv")
    audit=(OUT/"audit/test_provenance_audit_report.md").read_text(encoding="utf-8")
    val=(OUT/"audit/downstream_validation_report.md").read_text(encoding="utf-8")
    pool10=next(x for x in allres if x["method"]=="PoolAdapt" and x["operating_point"]=="B10")
    pool50=next(x for x in allres if x["method"]=="PoolAdapt" and x["operating_point"]=="B50")
    fcounts={c:sum(x["failure_category"]==c for x in cases) for c in ("under-allocation candidate","over-allocation candidate","high-latency case")}
    elems=[]
    elems += [p("PoolAdapt Improvement 1 Evaluation Report","Title"),p("Frozen TEST evaluation, paired analysis, Pareto trade-offs, and failure review","Subtitle"),p("Analysis of the completed SciFact TEST handoff | 12 November 2026"),p("Abstract","Heading1")]
    elems += [p(f"This report evaluates PoolAdapt against fixed-prefix and other candidate-selection methods using the frozen 300-query SciFact TEST set. The handoff contains 11,100 execution rows across 37 method/operating-point/seed strata. The primary paired comparisons use B10, B20, and B50, where actual pair-count means fall within the prespecified ±5% matching threshold. PoolAdapt averages {fnum(pool10,'ndcg_at_10'):.4f} nDCG@10 at B10 and {fnum(pool50,'ndcg_at_10'):.4f} at B50. Across all nine primary paired tests, Holm-adjusted permutation p-values are not below 0.05; intervals and effects are reported below. Pair consumption is substantially below the 100-pair Full Rerank reference, but observed reranking latency has long tails at several operating points. The provenance audit retains two FAIL and three NOT VERIFIED items, and the original TEST handoff controller fields remain unavailable. A later supplementary Query-group Analysis reconstructs descriptive groups; it does not populate those handoff fields or validate an adaptive policy. The evidence supports a quality-efficiency trade-off description, not a claim of causal superiority or complete historical reproducibility.")]

    elems += [p("Research objective and questions","Heading1"),p("The evaluation asks whether PoolAdapt can preserve retrieval quality while reducing the number of candidates sent to the cross-encoder, how it compares with Fixed Prefix at matched actual pair budgets, whether the observed operating points are Pareto efficient, and whether reranking latency tails align with actual pair counts. All analyses use frozen TEST outputs; no retrieval, reranking, training, or model inference was rerun.")]
    elems += [p("Experimental context and frozen TEST setup","Heading1"),p("The source evaluation records a Tesla T4 on cuda:0, CUDA 13.0, and Python 3.11.15. The recorded latency measures pair preparation, cross-encoder inference, and sorting. It excludes retrieval, selection, model loading, and warm-up, so it is reranking-stage latency rather than end-to-end latency. Methods include PoolAdapt, Fixed Prefix, SAGE-SLO, PACE-EF, Random, and Full Rerank. Operating points are B10, B20, B30, B50, and Full Rerank B100.")]
    elems += [p("Dataset and method overview","Heading1"),p("The TEST handoff covers 300 unique SciFact queries and 339 positive qrels judgments. Each method/operating-point/seed stratum covers the same 300 query IDs. Random has five genuine execution seeds (0–4) per query and operating point. For cross-query summaries, the five seed measurements are averaged within each query; the resulting independent population remains 300 queries. Non-Random methods have one execution per query and operating point.")]
    seed_body=[]
    for r in random_seeds:
        seed_body.append([r["operating_point"],r["seed_count"],f'{fnum(r,"ndcg_at_10_seed_mean"):.4f} ± {fnum(r,"ndcg_at_10_seed_sd"):.4f}',f'{fnum(r,"recall_at_10_seed_mean"):.4f} ± {fnum(r,"recall_at_10_seed_sd"):.4f}',f'{fnum(r,"mrr_at_10_seed_mean"):.4f} ± {fnum(r,"mrr_at_10_seed_sd"):.4f}',f'{fnum(r,"average_actual_pairs_seed_mean"):.2f}'])
    elems.append(p("Random seed sensitivity","Heading2"))
    elems.append(p("Seed SD describes variation among five seed-level 300-query means. It is reported separately from paired query-level uncertainty and is not used as an independent-query sample size."))
    elems.append(table(["Point","Seeds","nDCG mean ± SD","Recall mean ± SD","MRR mean ± SD","Pairs/q"],seed_body,[950,650,1900,1900,1900,1200]))
    elems += [p("Random latency percentile standardization","Heading2"),p("The primary Random latency estimand first averages the five seed observations within each query and operating point, then calculates P50 and P95 across the 300 query means. This preserves the frozen query as the independent population. The sensitivity table also shows the median and range of the five per-seed percentiles, the pooled 1,500 query-seed percentile distribution, and the historical source-summary values, which are means of per-seed percentiles. The pooled distribution combines query and seed variation and is not treated as 1,500 independent queries.")]
    latency_sens_body=[]
    for r in latency_sensitivity:
        latency_sens_body.append([r["operating_point"],f'{fnum(r,"primary_p50_ms"):.2f} / {fnum(r,"primary_p95_ms"):.2f}',f'{fnum(r,"seed_p50_median_ms"):.2f} [{fnum(r,"seed_p50_min_ms"):.2f}, {fnum(r,"seed_p50_max_ms"):.2f}]',f'{fnum(r,"seed_p95_median_ms"):.2f} [{fnum(r,"seed_p95_min_ms"):.2f}, {fnum(r,"seed_p95_max_ms"):.2f}]',f'{fnum(r,"pooled_query_seed_p50_ms"):.2f} / {fnum(r,"pooled_query_seed_p95_ms"):.2f}',f'{fnum(r,"historical_mean_seed_p50_ms"):.2f} / {fnum(r,"historical_mean_seed_p95_ms"):.2f}'])
    elems.append(table(["Point","Primary P50 / P95","Per-seed P50 median [range]","Per-seed P95 median [range]","Pooled P50 / P95","Historical P50 / P95"],latency_sens_body,[700,1150,1650,1650,1150,1500]))
    elems += [p("Data validation and provenance audit","Heading1"),p("Downstream checks passed for 11,100 rows, 11,100 unique composite keys, 37 strata, complete 300-query coverage in each stratum, valid [0,1] retrieval metrics, finite nonnegative latency, selected_k equal to actual reranked pairs, execution-manifest linkage, and positive-qrels coverage. Blank controller_features, query_group, and execution_id values remain unavailable; they are not interpreted as zeros. The downstream input manifest records current observed hashes and explicitly does not present them as historical output hashes.")]
    elems += [p("The upstream provenance audit reports 12 PASS, two FAIL, and three NOT VERIFIED. The FAIL items concern a historical hash mismatch for experiments/run_phase2_evaluation.py and mismatches for provenance amendment/reviewed source manifest hashes relative to historical execution-manifest values. The three NOT VERIFIED items concern missing TEST controller feature/query-group data, absent explicit execution ID/timestamp, and the lack of frozen output hashes for predictions/metrics. Current reviewed source files match the current source manifest, but this does not repair the historical mismatch. Therefore, this report does not claim complete historical reproducibility.")]
    elems += [p("The downstream reproduction check matches source summary values under their documented aggregation rules. The eight historical Random P50/P95 fields use means of per-seed percentiles; standardized primary values instead compute percentiles over 300 within-query seed means. Both estimates are retained and labeled in latency_cost/random_latency_percentile_sensitivity.csv. The primary values in this report follow the query-level estimand; historical fields are not validation targets for that different estimand.")]
    elems += [p("Metric definitions","Heading1"),p("Quality is measured with nDCG@10, Recall@10, and MRR@10. Average K is the selector's average candidate count. Average actual reranked pairs is the recorded workload per query. Compression ratio is method mean actual pairs divided by the Full Rerank mean actual pairs; pair-consumption reduction is one minus that ratio. These are pair-count comparisons, not monetary savings, billed GPU cost, or latency reduction. For Random, each query's latency is the arithmetic mean across seeds 0-4; cross-query latency percentiles are then calculated across the 300 query means. Non-Random methods have one recorded observation per query and operating point. Each aggregate uses the same frozen TEST population; no per-query compression ratios are averaged.")]
    elems += [p("Matched-budget methodology","Heading1"),p("The primary PoolAdapt versus Fixed Prefix budget comparison uses actual average pair counts and a ±5% tolerance. B10, B20, and B50 satisfy that criterion; B30 differs by more than 5% and is supplementary only. Paired statistics align each method by query_id. Full Rerank B100 supplies the 100-pair normalization reference.")]
    elems += [p("Matched-budget results","Heading1")]
    mbody=[]
    for r in match:
        mbody.append([r["method"],r["operating_point"],r["n_queries"],f'{fnum(r,"average_actual_pairs"):.2f}',f'{fnum(r,"ndcg_at_10"):.4f}',f'{fnum(r,"recall_at_10"):.4f}',f'{fnum(r,"mrr_at_10"):.4f}',f'{fnum(r,"compression_ratio"):.3f}',f'{fnum(r,"pair_cost_reduction"):.1%}',r["comparison_status"]])
    elems.append(table(["Method","Point","n","Pairs/q","nDCG","Recall","MRR","Ratio","Pair reduction","Status"],mbody,[1050,650,400,800,750,750,700,650,900,2400]))
    elems += [p("PoolAdapt and Fixed Prefix show similar aggregate quality at the primary matched budgets. PoolAdapt's actual pair count is 2.67% above Fixed Prefix at B10, 4.17% above at B20, and 1.33% below at B50. B30 is explicitly labeled supplementary because its pair means differ by 9.56%. The figure uses the same query-level aggregation and makes no significance claim.")]
    elems.append(image_block(OUT/"figures/matched_budget_quality_comparison.png",1,"Figure 1. Matched-budget quality scores for PoolAdapt and Fixed Prefix."))
    elems += [p("Paired statistical analysis","Heading1"),p("For each metric at B10, B20, and B50, paired differences are PoolAdapt minus Fixed Prefix on the same 300 queries. Confidence intervals use 10,000 paired query-level bootstrap resamples with seed 20261112. Two-sided permutation p-values use 100,000 Monte Carlo sign flips and a plus-one correction. Holm adjustment is applied across the three operating-point comparisons separately for each metric. Supplementary Wilcoxon signed-rank tests exclude zero differences. Cohen's dz divides the mean paired difference by its sample standard deviation; undefined statistics remain blank. A nonsignificant result is not evidence of equivalence.")]
    sbody=[]
    for r in stats:
        sbody.append([r["operating_point"],r["metric"],r["n_queries"],f'{fnum(r,"mean_paired_difference"):.5f}',f'[{fnum(r,"bootstrap_95_ci_low"):.5f}, {fnum(r,"bootstrap_95_ci_high"):.5f}]',f'{fnum(r,"permutation_p_raw"):.4f}',f'{fnum(r,"permutation_p_holm_adjusted"):.4f}',f'{fnum(r,"cohen_dz"):.4f}'])
    elems.append(table(["Point","Metric","n","Mean Δ","Bootstrap 95% CI","Raw p","Holm p","Cohen dz"],sbody,[700,1100,500,1000,2300,850,850,900]))
    elems += [p("No Holm-adjusted primary permutation test reaches 0.05. The B10 mean differences are small (nDCG +0.00085, Recall +0.00233, MRR approximately 0); B20 differences favor Fixed Prefix slightly on average; B50 differences favor PoolAdapt slightly. Confidence intervals include zero for all nine metric-budget comparisons. These results do not establish equivalence or superiority.")]
    elems += [p("Pareto analysis","Heading1"),p("Pair consumption and measured reranking latency are treated as separate objectives. For each, nDCG@10 is maximized while the corresponding resource is minimized. Pareto status is calculated across all method/operating points, including Full Rerank. A point is dominated only if another has no greater resource use and no lower nDCG@10, with at least one strict improvement; exact ties remain non-dominated. The output marks both efficient and dominated points and includes the comparison subset.")]
    for obj,title,img in [("quality_vs_actual_pairs","Quality versus actual pair consumption","quality_cost_pareto.png"),("quality_vs_reranking_latency","Quality versus measured reranking latency","quality_latency_pareto.png")]:
        efficient=[r for r in pareto if r["pareto_objective"]==obj and r["pareto_efficient"]=="True"]
        elems.append(p("Non-dominated points for "+title+": "+("; ".join(f"{r['method']} {r['operating_point']} (nDCG {fnum(r,'ndcg_at_10'):.4f})" for r in efficient) if efficient else "none")))
        elems.append(image_block(OUT/"pareto"/img,2 if "pairs" in obj else 3,"Pareto frontier for "+title+"."))
    elems.append(image_block(OUT/"pareto/operating_point_comparison.png",4,"Operating-point overview across methods."))
    elems += [p("Query-group analysis","Heading1"),p("Original TEST handoff status: UNAVAILABLE. The original handoff did not contain validated retrieval-ambiguity groups or controller features. A later supplementary Query-group Analysis reconstructs descriptive groups from available retrieval artifacts; it does not recover historical controller inputs or validate an adaptive policy. See query_group_analysis/evaluation/report_en.md and report_vi.md."),p("The authoritative handoff contains exactly 300 frozen TEST query IDs and query text, but its controller_features and query_group fields are blank. The frozen TEST predictions contain ranking IDs and execution outputs without per-query BM25 or dense scores/ranks, RRF scores, or saved retrieval feature vectors. Existing Phase 2 query_features.csv, pool_features.csv, and candidate_features.csv cover 809 train/validation IDs with zero overlap against the 300 TEST IDs; the Phase 2 Easy/Hard labels are based on qrels-derived M* outcomes and cannot be transferred. Query length could be tokenized from frozen query text before reranking, but it measures text length rather than candidate-set overlap or decisiveness of retrieval evidence, so a median split would not support the requested ambiguity interpretation. The supplementary analysis is separate: its reconstructed retrieval features and descriptive groups are not historical controller features. No feature or group label is inferred from evaluation outcomes in this original handoff assessment, and this Improvement 1 report does not include a query-group comparison figure. See audit/phase2_easy_hard_reuse_assessment.md and audit/data_handoff_specification.md.")]
    elems += [p("Failure analysis","Heading1"),p(f"Failure categories were declared before case selection and are evaluated only at primary matched budgets B10, B20, and B50. Under-allocation candidates require fewer actual pairs than same-point Fixed Prefix and an nDCG@10 decrease of at least 0.20. Over-allocation candidates require at least 10% and at least two more actual pairs than Fixed Prefix, with no nDCG@10 gain. The CSV preserves every qualifying query/point; the allocation figure shows the highest-magnitude qualifying cases in both categories. Counts are {fcounts['under-allocation candidate']} under-allocation candidates, {fcounts['over-allocation candidate']} over-allocation candidates, and {fcounts['high-latency case']} representative high-latency cases. The latter are the top three Tukey outliers in each of PoolAdapt B20, B30, and B50. Full Rerank per-query metrics are included as context.")]
    elems += [p("These are descriptive screening categories, not confirmed root causes. The primary handoff contains no controller features or query-group fields; the later supplementary Query-group Analysis reconstructs sparse/dense disagreement and pool descriptors, but does not provide historical controller inputs or establish a causal mechanism. Proposed selector follow-up requires a separately designed policy evaluation.")]
    elems.append(image_block(OUT/"figures/failure_case_examples.png",5,"Per-query cases ordered by predeclared threshold magnitude."))
    elems += [p("Latency-tail investigation","Heading1"),p("Latency distributions are summarized per query after averaging Random seeds within query. The Random P50/P95 values in the main results table use the standardized query-level mean convention; per-seed and pooled query-seed sensitivity estimates are reported above. High latency is defined consistently within each method/operating point as latency above Q3 + 1.5×IQR; no observation is removed. The table reports mean, P50, P75, P90, P95, P99, standard deviation, IQR, the P95–P50 gap, high-latency count, and Spearman associations with actual pairs and quality metrics. Linear pair-count model R² and residual SD are included to show remaining variation after a simple count adjustment; this descriptive model does not establish causality.")]
    tail=[("PoolAdapt","B20"),("PoolAdapt","B30"),("PoolAdapt","B50"),("SAGE-SLO","B20"),("SAGE-SLO","B30")]
    lbody=[]
    for m,b in tail:
        r=next(x for x in lat if x["method"]==m and x["operating_point"]==b)
        lbody.append([m,b,f'{fnum(r,"mean_ms"):.1f}',f'{fnum(r,"p50_ms"):.1f}',f'{fnum(r,"p75_ms"):.1f}',f'{fnum(r,"p90_ms"):.1f}',f'{fnum(r,"p95_ms"):.1f}',f'{fnum(r,"p99_ms"):.1f}',f'{fnum(r,"std_ms"):.1f}',f'{fnum(r,"iqr_ms"):.1f}',f'{fnum(r,"p95_minus_p50_ms"):.1f}',f'{r["high_latency_query_count"]}/{r["n_queries"]}'])
    elems.append(table(["Method","Point","Mean","P50","P75","P90","P95","P99","SD","IQR","P95−P50","High/n (ms)"],lbody,[900,500,700,700,700,700,700,700,700,700,800,900]))
    corr_lines=[]
    for m,b in tail:
        r=next(x for x in lat if x["method"]==m and x["operating_point"]==b)
        corr_lines.append(f"{m} {b}: Spearman latency-vs-pairs ρ={fnum(r,'spearman_latency_vs_actual_reranked_pairs'):.2f}; linear pair-count R²={fnum(r,'latency_pairs_linear_r2'):.2f}; residual SD={fnum(r,'latency_pairs_residual_std_ms'):.1f} ms")
    high_examples=[x for x in cases if x["failure_category"]=="high-latency case"]
    elems.append(p("Pair-count and residual checks: "+"; ".join(corr_lines)+". Representative high-latency query IDs and measured values: "+"; ".join(f"Q{x['query_id']} {x['operating_point']} ({float(x['criterion_value']):.1f} ms)" for x in high_examples)+"."))
    elems += [p("PoolAdapt B20 shows a large P95–P50 gap, as do PoolAdapt B30/B50 and SAGE-SLO B20/B30. High-latency cases occur in a small subset under the Tukey rule, though PoolAdapt B50 has a broader upper tail. Pair counts are strongly rank-associated with latency for adaptive methods where K varies, but Fixed Prefix has no pair-count variation within a point, so its pair-count correlation is undefined. Residual variation remains after linear pair adjustment. Available logs do not support attribution to GPU contention, thermal throttling, or background load.")]
    elems.append(image_block(OUT/"figures/latency_comparison.png",6,"Mean reranking latency bars with whiskers to P95."))
    elems.append(image_block(OUT/"figures/latency_distribution.png",7,"Per-query latency distributions for the five required strata."))
    elems += [p("Cost and efficiency","Heading1"),p("Average K and actual reranked pairs coincide in this handoff because every record passed selected_k = actual_reranked_pairs. Compression and pair-consumption reduction are relative to Full Rerank's observed 100 pairs/query. At B10, PoolAdapt averages 10.27 pairs/query (ratio 0.103); at B20 it averages 20.83 (ratio 0.208); at B50 it averages 49.33 (ratio 0.493). This corresponds to pair-count reductions of 89.73%, 79.17%, and 50.67%. These figures do not represent billed compute cost or measured latency reduction. Mean latency can exhibit long tails and does not scale exactly with average pair count.")]
    cost_body=[]
    for r in allres:
        cost_body.append([r["method"],r["operating_point"],f'{fnum(r,"average_k"):.2f}',f'{fnum(r,"average_actual_pairs"):.2f}',f'{fnum(r,"compression_ratio"):.3f}',f'{fnum(r,"pair_cost_reduction"):.1%}',f'{fnum(r,"mean_reranking_latency_ms"):.1f}',f'{fnum(r,"p50_reranking_latency_ms"):.1f}',f'{fnum(r,"p95_reranking_latency_ms"):.1f}'])
    elems.append(table(["Method","Point","Avg K","Pairs/q","Ratio","Pair reduction","Mean ms","P50 ms","P95 ms"],cost_body,[1350,650,750,900,800,1250,900,850,850]))
    elems.append(image_block(OUT/"figures/reranking_cost_comparison.png",8,"Mean actual pair consumption by method and operating point."))
    elems.append(image_block(OUT/"figures/k_distribution.png",9,"Per-query selected-K median and P10–P90 distributions."))
    elems += [p("Discussion","Heading1"),p("Across the three matched budgets, the aggregate quality differences are small and the paired inferential results do not show Holm-adjusted evidence of a difference at the 0.05 level. PoolAdapt spends slightly more pairs than Fixed Prefix at B10/B20 and slightly fewer at B50. The descriptive B30 result has a higher actual PoolAdapt budget and cannot support a matched-budget claim. Long latency tails matter for deployment decisions even where mean pair consumption is lower; a cost policy based only on average K would miss this operational variation.")]
    elems += [p("Threats to validity and limitations","Heading1"),p("The available evidence inherits two provenance hash failures and three unverified provenance items. The original TEST handoff lacks controller features and query_group values. A later supplementary analysis reconstructs descriptive retrieval features and groups, but these are not verified historical controller inputs and do not validate a policy; query length alone is not treated as a substitute. Explicit execution identifiers and timestamps are also unavailable. The recorded latency excludes retrieval, selection, model loading, and warm-up. Random seed aggregation is standardized by averaging within query; the reported sensitivity analyses describe seed variability but do not treat seeds as independent queries. The simple bootstrap and sign-flip procedures quantify paired query-level uncertainty under the specified resampling/null procedure; they do not establish equivalence. The failure criteria are screening thresholds. The pair-count linear latency fit and correlations are descriptive and cannot identify a causal latency mechanism. No monetary pricing or GPU billing data are available.")]
    elems += [p("Conclusion","Heading1"),p("The frozen handoff supports a reproducible downstream comparison on 300 SciFact TEST queries. PoolAdapt and Fixed Prefix have similar observed quality at B10, B20, and B50 actual pair budgets, with no Holm-adjusted paired test below 0.05. PoolAdapt reduces pair consumption relative to Full Rerank, while latency tails and provenance limitations remain material. The results support describing an efficiency-quality trade-off; they do not demonstrate equivalence, causal mechanism, complete historical reproducibility, or monetary savings.")]
